<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { addOrderNote, cancelOrder, dispatchReservation, fetchDriverLocation, fetchFareItems, fetchOrderDetail, fetchOrderNotes } from '@/api/orders'
import type { AdminDriverLocation, AdminFareItem, AdminOrderDetail, AdminOrderNote, OrderStatus } from '@/types/api'

const route = useRoute(); const router = useRouter(); const orderNo = String(route.params.orderNo); const detail = ref<AdminOrderDetail | null>(null); const notes = ref<AdminOrderNote[]>([]); const items = ref<AdminFareItem[]>([]); const location = ref<AdminDriverLocation | null>(null); const loading = ref(false); const error = ref(''); const note = ref(''); let timer: number | undefined
const labels: Record<OrderStatus, string> = { SCHEDULED: '等待派单', PENDING: '待抢单', ACCEPTED: '已接单', DRIVER_ARRIVED: '司机已到达', IN_SERVICE: '服务中', COMPLETED: '已完成', TERMINATED: '中途结束', CANCELLED: '已取消' }
function format(value: string | null) { return value ? value.replace('T', ' ') : '—' }; function money(value: number) { return `¥${Number(value).toFixed(2)}` }
async function load() { loading.value = true; error.value = ''; try { const [order, orderNotes, fare] = await Promise.all([fetchOrderDetail(orderNo), fetchOrderNotes(orderNo), fetchFareItems(orderNo)]); detail.value = order; notes.value = orderNotes; items.value = fare; try { location.value = await fetchDriverLocation(orderNo) } catch { location.value = null } } catch (reason) { error.value = reason instanceof Error ? reason.message : '加载订单详情失败。' } finally { loading.value = false } }
async function dispatch() { const reason = window.prompt('请输入提前派单原因：'); if (!reason?.trim()) return; try { await dispatchReservation(orderNo, reason.trim()); await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : '提前派单失败。' } }
async function cancel() { const reason = window.prompt('请输入取消原因：'); if (!reason?.trim()) return; try { await cancelOrder(orderNo, reason.trim()); await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : '取消订单失败。' } }
async function submitNote() { if (!note.value.trim()) return; try { await addOrderNote(orderNo, note.value.trim()); note.value = ''; await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : '追加备注失败。' } }
onMounted(() => { void load(); timer = window.setInterval(() => { if (!document.hidden) void load() }, 10000) }); onUnmounted(() => { if (timer) window.clearInterval(timer) })
</script>

<template><div class="detail-page"><button class="back" @click="router.back()">返回订单列表</button><div v-if="loading && !detail" class="panel empty">正在加载...</div><p v-if="error" class="error">{{ error }}</p><template v-if="detail"><header class="detail-header"><div><p class="eyebrow">订单 {{ detail.orderNo }}</p><h1>{{ detail.pickupName }} → {{ detail.destinationName }}</h1><p>{{ detail.orderType === 'SCHEDULED' ? `预约时间：${format(detail.scheduledPickupTime)}` : '即时订单' }}</p></div><span class="status large" :class="detail.status.toLowerCase()">{{ labels[detail.status] }}</span></header><div class="detail-grid"><section class="panel"><h2>订单与费用</h2><dl><dt>创建时间</dt><dd>{{ format(detail.createdTime) }}</dd><dt>派单时间</dt><dd>{{ format(detail.dispatchTime) }}</dd><dt>接单时间</dt><dd>{{ format(detail.acceptedTime) }}</dd><dt>总金额</dt><dd>{{ money(detail.totalFare) }}（{{ detail.estimatedFare ? '预估' : '已结算' }}）</dd></dl><div class="fare-list"><div v-for="item in items" :key="`${item.chargeType}-${item.amount}`"><span>{{ item.chargeType }}</span><strong>{{ money(item.amount) }}</strong></div></div></section><section class="panel"><h2>乘客与司机</h2><dl><dt>乘客</dt><dd>{{ detail.passengerPhoneTail ? `尾号 ${detail.passengerPhoneTail}` : '—' }}</dd><dt>司机</dt><dd>{{ detail.driver?.displayPhone || '尚未接单' }}</dd><dt>车辆</dt><dd>{{ detail.driver?.carNumber || '—' }}</dd><dt>最后位置</dt><dd v-if="location">{{ location.latitude }}, {{ location.longitude }}<small>{{ format(location.receivedTime) }}</small></dd><dd v-else>暂无位置</dd></dl></section><section class="panel"><h2>运营操作</h2><p class="muted">仅等待派单和待抢订单允许管理员取消；仅等待派单的预约订单允许提前派单。</p><div class="actions"><button v-if="detail.orderType === 'SCHEDULED' && detail.status === 'SCHEDULED'" @click="dispatch">提前派单</button><button v-if="detail.status === 'SCHEDULED' || detail.status === 'PENDING'" class="danger-button" @click="cancel">取消订单</button></div><form class="note-form" @submit.prevent="submitNote"><label>运营备注<textarea v-model="note" maxlength="500" placeholder="追加不可修改的运营备注" /></label><button :disabled="!note.trim()">追加备注</button></form><div class="note-list"><article v-for="item in notes" :key="item.id"><strong>{{ item.adminName }}</strong><small>{{ format(item.createdTime) }}</small><p>{{ item.content }}</p></article><p v-if="!notes.length" class="muted">暂无运营备注</p></div></section><section class="panel wide"><h2>状态时间线</h2><ol class="timeline"><li v-for="event in detail.events" :key="`${event.eventType}-${event.createdTime}`"><strong>{{ event.eventType }}</strong><span>{{ event.fromStatus || '创建' }} → {{ event.toStatus }}</span><small>{{ format(event.createdTime) }} · {{ event.operatorType }}</small><p v-if="event.remark">{{ event.remark }}</p></li></ol></section></div></template></div></template>
